import{_ as t,c as o,o as a,ae as r}from"./chunks/framework.DCU7Csu6.js";const p=JSON.parse('{"title":"Stock Management Migration: sku → chrtId","description":"","frontmatter":{},"headers":[],"relativePath":"guides/stocks-sku-to-chrtid-migration.md","filePath":"guides/stocks-sku-to-chrtid-migration.md"}'),s={name:"guides/stocks-sku-to-chrtid-migration.md"};function d(c,e,i,n,l,h){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="stock-management-migration-sku-→-chrtid" tabindex="-1">Stock Management Migration: <code>sku</code> → <code>chrtId</code> <a class="header-anchor" href="#stock-management-migration-sku-→-chrtid" aria-label="Permalink to &quot;Stock Management Migration: `sku` → `chrtId`&quot;">​</a></h1><blockquote><p><strong>Status</strong>: Stub — full migration guide will be published in task-16.5 (v3.12.0).</p><p><strong>Hard deadline</strong>: 2026-05-20 13:00 MSK — Wildberries begins gradually disabling the <code>sku</code> parameter on the seller-warehouse stock endpoints. After the deadline: HTTP 400 from WB.</p></blockquote><h2 id="why-this-matters" tabindex="-1">Why this matters <a class="header-anchor" href="#why-this-matters" aria-label="Permalink to &quot;Why this matters&quot;">​</a></h2><p>WB announced on 2026-05-08 (<a href="https://dev.wildberries.ru/release-notes?id=522" target="_blank" rel="noreferrer">https://dev.wildberries.ru/release-notes?id=522</a>) that the <code>sku</code> (barcode) parameter on three stock-management endpoints is being phased out in favor of <code>chrtId</code> (size ID from <code>POST /content/v2/get/cards/list</code>).</p><p>The SDK v3.12.0 adds <code>chrtId</code> / <code>chrtIds</code> support to:</p><ul><li><code>sdk.products.getStocks(warehouseId, { chrtIds: [...] })</code></li><li><code>sdk.products.updateStock(warehouseId, { stocks: [{ chrtId, amount }] })</code></li><li><code>sdk.products.deleteStock(warehouseId, { chrtIds: [...] })</code></li></ul><p>The legacy <code>sku</code>/<code>skus</code> parameters remain accepted (backwards-compatible) but are marked <code>@deprecated</code> and will emit a <code>console.warn</code> (since v3.12.0). They will be REMOVED in a future major version.</p><h2 id="how-to-get-a-chrtid" tabindex="-1">How to get a <code>chrtId</code> <a class="header-anchor" href="#how-to-get-a-chrtid" aria-label="Permalink to &quot;How to get a `chrtId`&quot;">​</a></h2><p>Call <code>POST /content/v2/get/cards/list</code> and read the <code>chrtID</code> field from each card&#39;s <code>sizes[]</code> array. The SDK exposes this via <code>sdk.products.getCardsList()</code>.</p><p><strong>Note on casing</strong>: WB uses <code>chrtID</code> (uppercase D) in Content API responses but <code>chrtId</code> (lowercase d) in this Marketplace stocks endpoint. Pass the same numeric value; the SDK property is <code>chrtId</code> (lowercase d) for stocks methods.</p><h2 id="full-migration-steps" tabindex="-1">Full migration steps <a class="header-anchor" href="#full-migration-steps" aria-label="Permalink to &quot;Full migration steps&quot;">​</a></h2><p>(See task-16.5 follow-up — this stub will be replaced by the complete guide.)</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./../../CHANGELOG.html">CHANGELOG v3.12.0</a></li><li>Source: <a href="https://dev.wildberries.ru/release-notes?id=522" target="_blank" rel="noreferrer">WB release-notes id=522</a></li></ul>',14)])])}const m=t(s,[["render",d]]);export{p as __pageData,m as default};
